protected void btnUpdateMarks_Click(object sender, EventArgs e)
{
    string studentCode, yearId, semester, planId;
    if (!TryDecodeStudentInfo(out studentCode, out yearId, out semester, out planId))
        return;

    try
    {
        POL_DoneDetail obj = new POL_DoneDetail();

        // Cập nhật từng dòng điểm giáo viên
        foreach (GridViewRow row in gvData.Rows)
        {
            if (row.RowType != DataControlRowType.DataRow) continue;

            int doneDetailID = Convert.ToInt32(gvData.DataKeys[row.RowIndex].Value);
            if (doneDetailID <= 0) continue;

            TextBox txtTeacherMark = row.FindControl("txtTeacherMark") as TextBox;
            if (txtTeacherMark == null) continue;

            decimal teacherMark = ParseDecimal(txtTeacherMark.Text);

            obj.GetDataTable("POL_DoneDetail_UpdateReviewMark",
                "@DoneDetailID", doneDetailID,
                "@ReviewMark", teacherMark);
        }

        // Cập nhật tổng điểm
        UpdateTotalMarks(obj, studentCode, yearId, semester, planId);

        MsgBox.ShowSuccess("Cập nhật điểm thành công!");
        LoadData();
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Có lỗi xảy ra trong quá trình cập nhật: " + ex.Message);
    }
}

private void UpdateTotalMarks(POL_DoneDetail obj, string studentCode, string yearId, string semester, string planId)
{
    DataTable dtbData = FilterEthicReportData(GetStudentData(studentCode, yearId, semester, planId), planId);
    if (dtbData == null || dtbData.Rows.Count == 0) return;

    decimal totalStudentMarks = 0, totalTeacherMarks = 0;

    foreach (DataRow dr in dtbData.Rows)
    {
        totalStudentMarks += ParseDecimal(dr["StudentMark"]);
        totalTeacherMarks += ParseDecimal(dr["TeacherMark"]);
    }

    // Nếu store này CHƯA có @PlanID thì bỏ dòng @PlanID đi
    obj.GetDataTable("POL_DoneDetail_UpdateReviewMark_Learning",
        "@StudentCode", studentCode,
        "@YearID", yearId,
        "@Semester", semester,
        "@PlanID", planId,
        "@totalStudent", totalStudentMarks,
        "@totalTeacher", totalTeacherMarks);
}

